# -*- coding: utf-8 -*-
import json
import re

# Load base 175 items from catalog.js
with open('catalog.js', 'r', encoding='utf-8') as f:
    cat_raw = f.read()

pattern = r'\{\s*id:\s*"([^"]+)",\s*title:\s*"([^"]+)",\s*year:\s*(\d+),\s*platform:\s*"([^"]+)",\s*platformName:\s*"([^"]+)",\s*format:\s*"([^"]+)",\s*runtime:\s*"([^"]+)",\s*imdb:\s*"([^"]+)",\s*rt:\s*"([^"]+)",\s*lang:\s*"([^"]+)",\s*langText:\s*"([^"]+)",\s*vibe:\s*"([^"]+)",\s*genres:\s*\[([^\]]*)\],\s*hook:\s*"([^"]+)",\s*searchUrl:\s*"([^"]+)"\s*\}'

base_175 = []
for m in re.finditer(pattern, cat_raw):
    g_raw = m.group(13)
    genres = [x.strip().strip('"').strip("'") for x in g_raw.split(',') if x.strip()]
    base_175.append({
        "id": m.group(1),
        "title": m.group(2),
        "year": int(m.group(3)),
        "platform": m.group(4),
        "platformName": m.group(5),
        "format": m.group(6),
        "runtime": m.group(7),
        "imdb": m.group(8),
        "rt": m.group(9),
        "lang": m.group(10),
        "langText": m.group(11),
        "vibe": m.group(12),
        "genres": genres,
        "hook": m.group(14),
        "searchUrl": m.group(15)
    })

# Load existing 60 from freshPullPool
with open('index.html', 'r', encoding='utf-8') as f:
    html_raw = f.read()

p_start = html_raw.find('const freshPullPool = [')
p_end = html_raw.find('const baseCatalog =', p_start)
pool_raw = html_raw[p_start:p_end]

pool_60 = []
for m in re.finditer(pattern, pool_raw):
    g_raw = m.group(13)
    genres = [x.strip().strip('"').strip("'") for x in g_raw.split(',') if x.strip()]
    pool_60.append({
        "id": m.group(1),
        "title": m.group(2),
        "year": int(m.group(3)),
        "platform": m.group(4),
        "platformName": m.group(5),
        "format": m.group(6),
        "runtime": m.group(7),
        "imdb": m.group(8),
        "rt": m.group(9),
        "lang": m.group(10),
        "langText": m.group(11),
        "vibe": m.group(12),
        "genres": genres,
        "hook": m.group(14),
        "searchUrl": m.group(15)
    })

existing_all = {x["id"] for x in base_175} | {x["id"] for x in pool_60}
print(f"Loaded {len(base_175)} base + {len(pool_60)} pool. Unique IDs: {len(existing_all)}")

