# Ensure no ID collision within base
base_ids = set()
clean_base = []
for item in base_175 + ADDITIONAL_BASE:
    if item["id"] not in base_ids:
        base_ids.add(item["id"])
        clean_base.append(item)

print(f"Total Unique Base in catalog.js: {len(clean_base)}")

# Ensure no ID collision in freshPullPool with clean_base
pool_ids = set()
clean_pool = []
for item in pool_60 + ADDITIONAL_POOL:
    if item["id"] not in base_ids and item["id"] not in pool_ids:
        pool_ids.add(item["id"])
        clean_pool.append(item)

print(f"Total Unique Pool in freshPullPool: {len(clean_pool)}")
print(f"Total Combined Offline Library: {len(clean_base) + len(clean_pool)}")

# Let's count by platform in clean_base
base_p_counts = {}
for x in clean_base:
    base_p_counts[x["platform"]] = base_p_counts.get(x["platform"], 0) + 1
print("Base platform counts:", base_p_counts)

# Let's count by platform in clean_pool
pool_p_counts = {}
for x in clean_pool:
    pool_p_counts[x["platform"]] = pool_p_counts.get(x["platform"], 0) + 1
print("Pool platform counts:", pool_p_counts)

# 1. Output catalog.js
def format_item(item):
    g_str = json.dumps(item["genres"])
    return f"""  {{
    id: "{item['id']}",
    title: {json.dumps(item['title'])},
    year: {item['year']},
    platform: "{item['platform']}",
    platformName: "{item['platformName']}",
    format: "{item['format']}",
    runtime: "{item['runtime']}",
    imdb: "{item['imdb']}",
    rt: "{item['rt']}",
    lang: "{item['lang']}",
    langText: "{item['langText']}",
    vibe: "{item['vibe']}",
    genres: {g_str},
    hook: {json.dumps(item['hook'])},
    searchUrl: "{item['searchUrl']}"
  }}"""

cat_lines = ["// StreamMood India - Comprehensive Curated OTT Catalog (325+ Titles)",
             "// Platforms: Netflix, Prime Video, JioHotstar, SonyLIV, Zee5",
             "",
             "window.initialCatalog = [",
             ",\n".join(format_item(x) for x in clean_base),
             "];",
             ""]

with open('catalog.js', 'w', encoding='utf-8') as f:
    f.write("\n".join(cat_lines))

print("Successfully written catalog.js with", len(clean_base), "titles!")

# 2. Output fresh_pull_pool.json and prepare for index.html replacement
pool_snippet = "    const freshPullPool = [\n" + ",\n".join(format_item(x) for x in clean_pool) + "\n    ];"

with open('scratch/pool_snippet.js', 'w', encoding='utf-8') as f:
    f.write(pool_snippet)

print("Successfully written scratch/pool_snippet.js with", len(clean_pool), "titles!")
